import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem70 preserva operação e identidade sem prometer resultados',()=>{for(const [id,titulo] of [['DuqIf8kBMwEZzRskn9LR','Poco X8 Pro Max 512gb 12gb Ram Global Bateria 8.500mah'],['e2JrkBA5LBbERAqFunqx','Micro-ondas 20l Prata Porta Espelhada Mastercook Midea']]){const p={id,titulo,preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/massacr|ideal|ultrarresistente|26 cm|autolimpante/i);}});
